    "questionEn": "Q10 (2025 CSAT Paper-II).\n\nA sum of money is divided between A, B, and C such that A receives 40% of the total amount, and the remaining amount is shared between B and C in the ratio 3 : 2. If A receives ₹1400 more than B, what is the total sum of money?",
    "questionHi": "प्रश्न 10 (2025 सिविल सेवा CSAT प्रश्नपत्र-II)।\n\nएक धनराशि को A, B और C के बीच इस प्रकार विभाजित किया जाता है कि A को कुल राशि का 40% प्राप्त होता है, तथा शेष राशि को B और C के बीच 3 : 2 के अनुपात में बांटा जाता है। यदि A को B से ₹1400 अधिक प्राप्त होते हैं, तो कुल धनराशि कितनी है?",
    "options": [
      {
        "id": "A",
        "text": "₹35000"
      },
      {
        "id": "B",
        "text": "₹28000"
      },
      {
        "id": "C",
        "text": "₹42000"
      },
      {
        "id": "D",
        "text": "₹21000"
      }
    ],
