    "solution": "Official Mathematical Derivation for Q18:\nLet total sum = T.\nA's share = 0.40 T.\nRemaining = 0.60 T.\nB's share = (3/5) * 0.60 T = 0.36 T.\nDifference (A - B) = 0.40 T - 0.36 T = 0.04 T = (1/25) T.\nGiven: (1/25) T = ₹1560 => T = ₹39000.\nHence, Option (A) is correct.",
    "solutionEn": "Official Mathematical Derivation for Q18:\nLet total sum = T.\nA's share = 0.40 T.\nRemaining = 0.60 T.\nB's share = (3/5) * 0.60 T = 0.36 T.\nDifference (A - B) = 0.40 T - 0.36 T = 0.04 T = (1/25) T.\nGiven: (1/25) T = ₹1560 => T = ₹39000.\nHence, Option (A) is correct.",
