    "solutionHi": "प्रश्न 42 का आधिकारिक गणितीय हल:\nमाना कुल राशि = T\nA का हिस्सा = 0.40 T\nशेष राशि = 0.60 T\nB का हिस्सा = (3/5) * 0.60 T = 0.36 T\nअंतर (A - B) = 0.40 T - 0.36 T = 0.04 T = T / 25\nप्रश्नानुसार: T / 25 = ₹2040 => T = ₹51000\nअतः विकल्प (A) सही उत्तर है।",
