    "questionEn": "Q59 (2025 CSAT Paper-II).\n\nSix persons P, Q, R, S, T, and U are seated around a circular table facing towards the center:\n1. P is seated second to the right of T.\n2. Q is an immediate neighbor of both R and S.\n3. U is seated immediately opposite to P.\nWho is seated immediately to the left of Q?",
    "questionHi": "प्रश्न 59 (2025 सिविल सेवा CSAT प्रश्नपत्र-II)।\n\nछह व्यक्ति P, Q, R, S, T और U एक वृत्ताकार मेज के चारों ओर केंद्र की ओर मुख करके बैठे हैं:\n1. P, T के दायें दूसरे स्थान पर बैठा है।\n2. Q, R और S दोनों का निकटतम पड़ोसी है।\n3. U, P के ठीक विपरीत बैठा है।\nQ के ठीक बायें कौन बैठा है?",
