    "solution": "Official Mathematical Derivation for Q62:\nLet total sum = T.\nA's share = 0.40 T.\nRemaining = 0.60 T.\nB's share = (3/5) * 0.60 T = 0.36 T.\nDifference (A - B) = 0.40 T - 0.36 T = 0.04 T = (1/25) T.\nGiven: (1/25) T = ₹2440 => T = ₹61000.\nHence, Option (A) is correct.",
    "solutionEn": "Official Mathematical Derivation for Q62:\nLet total sum = T.\nA's share = 0.40 T.\nRemaining = 0.60 T.\nB's share = (3/5) * 0.60 T = 0.36 T.\nDifference (A - B) = 0.40 T - 0.36 T = 0.04 T = (1/25) T.\nGiven: (1/25) T = ₹2440 => T = ₹61000.\nHence, Option (A) is correct.",
    "solutionHi": "प्रश्न 62 का आधिकारिक गणितीय हल:\nमाना कुल राशि = T\nA का हिस्सा = 0.40 T\nशेष राशि = 0.60 T\nB का हिस्सा = (3/5) * 0.60 T = 0.36 T\nअंतर (A - B) = 0.40 T - 0.36 T = 0.04 T = T / 25\nप्रश्नानुसार: T / 25 = ₹2440 => T = ₹61000\nअतः विकल्प (A) सही उत्तर है।",
